            f=cho_factor(K[:n,:n]+lam*I,check_finite=False); alpha=cho_solve(f,target,check_finite=False); inv=cho_solve(f,I,check_finite=False).diagonal(); e=np.mean(abs(alpha/inv[:,None]),axis=0)
            pred=K[n:,:n]@alpha
